body {
    font-family: "Inter", sans-serif;
    font-size: 18px;
    line-height: 1.5; /* Unitless value is crucial for responsiveness */
    color: #333;
}

h1 {
    font-family: "Playfair Display", serif;
    font-size: 48px;
    line-height: 1.15; /* Tighter for headings for visual impact */
    color: #1a1a1a;
}

.small-print {
    font-size: 14px;
    line-height: 1.3; /* Can be slightly tighter for smaller text */
    color: #666;
}
